// Multiple Inheritance Vptr Adjustment Overhead
class B1 { virtual void f1() = 0; }; // vptr at offset 0
class B2 { virtual void f2() = 0; }; // vptr at offset > 0
class Derived : public B1, public B2 {
    void f1() override {}
    void f2() override {}
};
// MI Constructor Overhead:
// 1. B1::B1() -> sets vptr0
// 2. B2::B2() -> sets vptr_offset
// 3. Derived::Derived() -> sets both final vptrs
// B2* ptr = new Derived(); // Pointer adjustment (thunk) required
// Cost: Extra arithmetic for 'this' pointer calculation in MI calls.
